/**
 * Normalizes strings for robust matching (lowercase, removes excess whitespace)
 */
function normalizeName(str = '') {
  return str.toLowerCase().replace(/\s+/g, ' ').trim();
}

/**
 * Finds a student's assigned project by exact or partial/case-insensitive name match.
 * @param {string} searchName
 * @returns {object|null} The matched student project or null
 */
export function getGenAiProjectForStudent(searchName) {
  if (!searchName || typeof searchName !== 'string') return null;
  const cleanSearch = normalizeName(searchName);
  if (!cleanSearch) return null;

  // 1. Exact match (case-insensitive)
  const exact = GENAI_PROJECTS.find(
    (p) => normalizeName(p.studentName) === cleanSearch
  );
  if (exact) return exact;

  // 2. Starts with / contains match (e.g. "Vicky" -> "Vicky Gupta", or "Atharv" -> "atharv sharma")
  const containsMatch = GENAI_PROJECTS.find((p) => {
    const studentNorm = normalizeName(p.studentName);
    return (
      studentNorm.startsWith(cleanSearch) ||
      cleanSearch.startsWith(studentNorm) ||
      studentNorm.includes(cleanSearch) ||
      cleanSearch.includes(studentNorm)
    );
  });
  if (containsMatch) return containsMatch;

  // 3. First name match
  const searchFirstName = cleanSearch.split(' ')[0];
  if (searchFirstName.length >= 3) {
    const firstNameMatch = GENAI_PROJECTS.find((p) => {
      const pFirst = normalizeName(p.studentName).split(' ')[0];
      return pFirst === searchFirstName;
    });
    if (firstNameMatch) return firstNameMatch;
  }

  return null;
}

/**
 * Returns a sorted list of all registered student names
 */
export const ALL_STUDENT_NAMES = GENAI_PROJECTS.map((p) => p.studentName).sort((a, b) =>
  a.localeCompare(b, undefined, { sensitivity: 'base' })
);
